const state={step:0,protein:false,calories:false,minProtein:10,maxCal:200,query:'energy bars',panel:false,draftProtein:false};
const guides=["The supplied screenshots place <strong>High Protein</strong> inside <strong>Filters \u2192 Suggested</strong>. The shown rows do not foreground protein grams. Open Filters to inspect this limited reference.", "Select <strong>High protein</strong> and choose a <strong>minimum protein amount per serving</strong>. Optionally select Low cal for a maximum calorie amount. Selecting a chip immediately applies its default. Edit an amount to update the matches.", "<strong>Both filters are selected.</strong> Edit either amount and inspect the matching rows. Each row shows protein grams, calories and the labeled serving size. Clear one chip to compare a single-filter result."];
